// ============================================================
// Router Node: Cek apakah request berasal dari Scan Foto
// Jika ada field `parsedItems` di body, skip Gemini AI dan
// langsung teruskan items yang sudah diparse oleh frontend.
// ============================================================

const body = $input.first().json?.body || $input.first().json || {};

const hasParsedItems = Array.isArray(body.parsedItems) && body.parsedItems.length > 0;

if (hasParsedItems) {
  // Foto scan path: return pre-parsed items as-is
  const todayStr = body.currentDate || new Date().toISOString().slice(0, 10);

  return body.parsedItems.map((item, index) => ({
    json: {
      index: index + 1,
      tanggal: item.tanggal || todayStr,
      kategori: item.kategori || 'Lain-lain',
      deskripsi: item.deskripsi || 'Pengeluaran',
      jumlah: Number(item.jumlah) || 0,
      total_nominal: Number(item.jumlah) || 0,
      _source: 'photo_scan'
    }
  })).filter(i => i.json.jumlah > 0);
} else {
  // Text path: pass through to Gemini AI node
  return [{ json: { ...body, _route: 'text' } }];
}

// ============================================================
// Branch Check: Skip Gemini if already routed from photo scan.
// Returns items if _source is photo_scan, otherwise returns
// data for Gemini AI processing.
// ============================================================

const items = $input.all();
const firstItem = items[0]?.json || {};

// If routed from photo (has _source: photo_scan), skip to append
if (firstItem._source === 'photo_scan') {
  return items; // pass through directly to Google Sheets
}

// Text route — pass to Gemini
return items;

// Node: Code Node (JSON Parser & Validation)
// Ultra-robust parser untuk output Gemini/n8n.

const rawOutput = $input.first().json;

function looksLikeExpenseObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) && (
    'tanggal' in value || 'kategori' in value || 'deskripsi' in value ||
    'jumlah' in value || 'nominal' in value || 'amount' in value ||
    'description' in value || 'category' in value || 'date' in value ||
    'price' in value || 'item' in value || 'harga' in value || 'cost' in value
  );
}

function findGeminiPayload(value, depth = 0) {
  if (value == null || depth > 6) return null;
  if (typeof value === 'string' && value.trim()) return value;
  if (Array.isArray(value)) return value;
  if (looksLikeExpenseObject(value)) return value;

  const candidateText = value.candidates?.[0]?.content?.parts?.map((p) => p?.text || '').join('\n');
  if (candidateText && candidateText.trim()) return candidateText;

  const partsText = value.content?.parts?.map((p) => p?.text || '').join('\n');
  if (partsText && partsText.trim()) return partsText;

  for (const key of ['text', 'response', 'output', 'message', 'result', 'data', 'json']) {
    if (value[key] != null) {
      const found = findGeminiPayload(value[key], depth + 1);
      if (found != null) return found;
    }
  }

  return null;
}

function sanitizeAndNormalizeJson(str) {
  if (!str || typeof str !== 'string') return '';
  return str
    .replace(/```json/gi, '')
    .replace(/```javascript/gi, '')
    .replace(/```js/gi, '')
    .replace(/```/g, '')
    .replace(/[\u201C\u201D\u201E\u201F\u2033\u2036]/g, '"')
    .replace(/[\u2018\u2019\u201A\u201B\u2032\u2035]/g, "'")
    .replace(/\bNone\b/g, 'null')
    .replace(/\bTrue\b/g, 'true')
    .replace(/\bFalse\b/g, 'false')
    .trim();
}

function tryParseCandidate(candidate) {
  if (!candidate || typeof candidate !== 'string') return null;
  const trimmed = candidate.trim();
  if (!trimmed) return null;

  try { return JSON.parse(trimmed); } catch (e) {}

  try {
    let fixed = trimmed
      .replace(/,\s*([\]}])/g, '$1')
      .replace(/'([^'\\]*(?:\\.[^'\\]*)*)'/g, '"$1"');
    return JSON.parse(fixed);
  } catch (e) {}

  try {
    const fn = new Function('return (' + trimmed + ')');
    const result = fn();
    if (result != null && (typeof result === 'object' || Array.isArray(result))) return result;
  } catch (e) {}

  return null;
}

function parseJsonText(text) {
  const cleaned = sanitizeAndNormalizeJson(text);
  if (!cleaned) return [];

  const direct = tryParseCandidate(cleaned);
  if (direct != null) return direct;

  const arrayStart = cleaned.indexOf('[');
  const arrayEnd = cleaned.lastIndexOf(']');
  if (arrayStart !== -1 && arrayEnd > arrayStart) {
    const parsed = tryParseCandidate(cleaned.slice(arrayStart, arrayEnd + 1));
    if (parsed != null) return parsed;
  }

  const objectStart = cleaned.indexOf('{');
  const objectEnd = cleaned.lastIndexOf('}');
  if (objectStart !== -1 && objectEnd > objectStart) {
    const parsed = tryParseCandidate(cleaned.slice(objectStart, objectEnd + 1));
    if (parsed != null) return parsed;
  }

  throw new Error('Gagal mengekstrak JSON dari teks AI: ' + cleaned.slice(0, 300));
}

function unwrapExpenseList(value) {
  let current = value;
  for (let i = 0; i < 5; i++) {
    if (typeof current === 'string') current = parseJsonText(current);
    if (Array.isArray(current)) return current;
    if (looksLikeExpenseObject(current)) return [current];
    if (current && typeof current === 'object') {
      const next = current.data || current.items || current.expenses || current.pengeluaran || current.transactions || current.output || current.response || current.text || current.result;
      if (next == null) break;
      current = next;
      continue;
    }
    break;
  }
  return [];
}

function parseNominal(value) {
  if (typeof value === 'number') return Math.round(value);
  const raw = String(value ?? '').toLowerCase().trim();
  const match = raw.match(/(\d+(?:[.,]\d+)?)\s*(rb|ribu|k|jt|juta)?/i);
  if (!match) return 0;
  const number = parseFloat(match[1].replace(',', '.'));
  const unit = match[2];
  if (unit === 'rb' || unit === 'ribu' || unit === 'k') return Math.round(number * 1000);
  if (unit === 'jt' || unit === 'juta') return Math.round(number * 1000000);
  return Math.round(number);
}

function guessCategory(desc) {
  const lower = (desc || '').toLowerCase();
  if (/kopi|makan|minum|sarapan|warteg|nasi|snack|gorengan|lontong|risol|roti|bakso|ayam|mie|sate|martabak|resto|lele/i.test(lower)) return 'Makanan & Minuman';
  if (/bensin|pertalite|pertamax|gojek|grab|parkir|tol|angkot|kereta|busway|oli|service/i.test(lower)) return 'Transportasi';
  if (/belanja|supermarket|indomaret|alfamart|sabun|galon|aqua|beras|minyak/i.test(lower)) return 'Belanja Kebutuhan';
  if (/listrik|pln|token|pulsa|kuota|wifi|internet|indihome|pdam|kontrakan|kost/i.test(lower)) return 'Tagihan & Utilitas';
  if (/obat|apotek|vitamin|dokter|klinik|masker/i.test(lower)) return 'Kesehatan';
  if (/bioskop|nonton|game|topup|steam|spotify|netflix/i.test(lower)) return 'Hiburan & Gaya Hidup';
  return 'Lain-lain';
}

function normalizeDate(rawDate, refDateStr) {
  const baseDate = refDateStr ? new Date(refDateStr) : new Date();
  const formatIso = (d) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };
  const todayStr = formatIso(baseDate);
  if (!rawDate || typeof rawDate !== 'string') return todayStr;
  const trimmed = rawDate.trim().toLowerCase();
  if (trimmed === 'kemarin' || trimmed === 'kmrn') { const d = new Date(baseDate); d.setDate(d.getDate() - 1); return formatIso(d); }
  if (trimmed === 'kemarin lusa' || trimmed === '2 hari lalu') { const d = new Date(baseDate); d.setDate(d.getDate() - 2); return formatIso(d); }
  if (trimmed === 'tadi' || trimmed === 'hari ini' || trimmed === 'barusan') return todayStr;
  const isoMatch = trimmed.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (isoMatch) {
    const y = parseInt(isoMatch[1], 10);
    const m = String(parseInt(isoMatch[2], 10)).padStart(2, '0');
    const d = String(parseInt(isoMatch[3], 10)).padStart(2, '0');
    const currentYear = baseDate.getFullYear();
    if (Math.abs(y - currentYear) > 1) return `${currentYear}-${m}-${d}`;
    return `${y}-${m}-${d}`;
  }
  return todayStr;
}

let expenseList = [];

try {
  const payload = findGeminiPayload(rawOutput);
  if (payload == null) throw new Error('Payload Gemini kosong/tidak dikenali. Raw: ' + JSON.stringify(rawOutput).slice(0, 500));
  expenseList = unwrapExpenseList(payload);
} catch (error) {
  throw new Error('Gagal melakukan parse JSON dari Gemini AI: ' + error.message);
}

let refDate = null;
try {
  const webhookInput = $('Webhook (Trigger)')?.first()?.json;
  refDate = webhookInput?.body?.currentDate || webhookInput?.currentDate;
} catch (e) {}

const validatedItems = expenseList.map((rawItem, index) => {
  const item = rawItem?.json || rawItem;
  let rawNominal = item?.jumlah ?? item?.nominal ?? item?.amount ?? item?.total ?? item?.price ?? item?.harga ?? item?.cost ?? item?.value ?? item?.val;
  if (rawNominal == null) {
    const k = Object.keys(item).find((k) => /jumlah|nominal|amount|total|price|harga|cost/i.test(k));
    if (k) rawNominal = item[k];
  }
  let nominal = parseNominal(rawNominal);
  let desc = item?.deskripsi || item?.description || item?.item || item?.nama || item?.name || item?.title || '';
  if (!desc) {
    const k = Object.keys(item).find((k) => /deskripsi|desc|nama|name|item|title/i.test(k));
    if (k) desc = item[k];
  }
  let cat = item?.kategori || item?.category;
  if (!cat) cat = guessCategory(desc);
  const tgl = normalizeDate(item?.tanggal || item?.date || item?.tgl, refDate);
  return {
    json: {
      index: index + 1,
      tanggal: tgl,
      kategori: cat,
      deskripsi: desc ? desc.charAt(0).toUpperCase() + desc.slice(1) : 'Pengeluaran',
      jumlah: nominal,
      total_nominal: nominal
    }
  };
}).filter((item) => item.json.jumlah > 0 && item.json.deskripsi);

if (validatedItems.length === 0) {
  throw new Error('Tidak ada item valid dari Gemini. Cek output node Gemini. Raw: ' + JSON.stringify(rawOutput).slice(0, 800));
}

return validatedItems;

